parameters.inputSchema:
{
  "name": "food_recipe_response",
  "schema": {
    "type": "object",
    "properties": {
      "dish_name": {
        "type": "string",
        "description": "The standard name of the dish"
      },
      "origin_cuisine": {
        "type": "string",
        "description": "Country or region of origin"
      },
      "short_definition": {
        "type": "string",
        "description": "1-2 sentence description of texture and flavor"
      },
      "difficulty_level": {
        "type": "string",
        "enum": ["Easy", "Medium", "Hard"]
      },
      "time_estimates": {
        "type": "object",
        "properties": {
          "prep_time": { "type": "string" },
          "cook_time": { "type": "string" }
        },
        "required": ["prep_time", "cook_time"]
      },
      "ingredients": {
        "type": "array",
        "items": { "type": "string" },
        "description": "List of ingredients with quantities"
      },
      "recipe_steps": {
        "type": "array",
        "items": { "type": "string" },
        "description": "Step-by-step cooking instructions"
      },
      "serving_info": {
        "type": "object",
        "properties": {
          "approx_grams": { "type": "integer" },
          "visual_size": { "type": "string" },
          "calories_kcal": { "type": "integer" }
        },
        "required": ["approx_grams", "visual_size", "calories_kcal"]
      },
      "dietary_alerts": {
        "type": "object",
        "properties": {
          "common_allergens": {
            "type": "array",
            "items": { "type": "string" }
          },
          "religious_restrictions": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Specific warnings for Halal, Kosher, Hindu, etc."
          },
          "dietary_type": {
            "type": "string",
            "description": "e.g., Vegan, Keto, Gluten-Free"
          }
        },
        "required": ["common_allergens", "religious_restrictions", "dietary_type"]
      }
    },
    "required": [
      "dish_name",
      "origin_cuisine",
      "short_definition",
      "difficulty_level",
      "time_estimates",
      "ingredients",
      "recipe_steps",
      "serving_info",
      "dietary_alerts"
    ],
    "additionalProperties": false
  },
  "strict": true
}
